import React, { useState } from 'react';
import { createTestDrive } from '../services/testDriveService';
import { useAuth } from '../context/AuthContext';

const TestDriveForm = ({ carId }) => {
  const { user } = useAuth();
  const [selectedDate, setSelectedDate] = useState('');
  const [selectedTime, setSelectedTime] = useState('');
  const [phone, setPhone] = useState('');
  const [message, setMessage] = useState('');
  const [success, setSuccess] = useState(false);
  const [error, setError] = useState('');

  // Генерируем следующие 5 дней начиная с сегодняшнего
  const getNextDays = () => {
    const days = [];
    const options = { weekday: 'short', day: 'numeric' };
    for (let i = 0; i < 5; i++) {
      const d = new Date();
      d.setDate(d.getDate() + i);
      
      const year = d.getFullYear();
      const month = String(d.getMonth() + 1).padStart(2, '0');
      const day = String(d.getDate()).padStart(2, '0');
      
      const dateStr = `${year}-${month}-${day}`; // Для бэкенда
      let label = d.toLocaleDateString('ru-RU', options);
      label = label.charAt(0).toUpperCase() + label.slice(1); // Капитализация дня недели
      
      days.push({ dateStr, label });
    }
    return days;
  };

  const timeSlots = ['10:00', '12:00', '14:00', '16:00', '18:00', '20:00'];

  const validatePhone = (value) => {
    const cleaned = value.replace(/\D/g, '');
    if (cleaned.length !== 11) return false;
    if (cleaned[0] !== '7' && cleaned[0] !== '8') return false;
    return true;
  };

  const formatPhone = (value) => {
    const digits = value.replace(/\D/g, '');
    if (digits.length === 0) return '';
    if (digits[0] === '8') return `8${digits.slice(1, 11)}`;
    return `+7${digits.slice(1, 11)}`;
  };

  const handlePhoneChange = (e) => {
    setPhone(formatPhone(e.target.value));
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!selectedDate || !selectedTime) {
      setError('Пожалуйста, выберите дату и время тест-драйва');
      return;
    }
    if (!validatePhone(phone)) {
      setError('Неверный формат телефона');
      return;
    }

    // Собираем в формат, который ждет бэкенд: YYYY-MM-DDTHH:mm
    const fullDateTime = `${selectedDate}T${selectedTime}`;

    try {
      await createTestDrive({ car_id: carId, date: fullDateTime, phone, message });
      setSuccess(true);
      setError('');
    } catch (err) {
      setError(err.response?.data?.detail || 'Ошибка при записи');
    }
  };

  if (success) {
    return (
      <div style={{ textAlign: 'center', padding: '1.5rem 0', color: 'var(--text)' }}>
        <h4 style={{ color: '#4CAF50', marginBottom: '0.5rem', fontSize: '1.4rem' }}>Успешно!</h4>
        <p style={{ opacity: 0.9, margin: 0, fontSize: '0.95rem', lineHeight: '1.5' }}>
          Вы успешно записались на тест-драйв. Менеджер свяжется с вами в ближайшее время.
        </p>
      </div>
    );
  }

  return (
    <form onSubmit={handleSubmit} style={{ display: 'flex', flexDirection: 'column', gap: '1.4rem' }}>
      
      {/* Выбор Дня */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
        <label style={{ fontSize: '0.85rem', fontWeight: '600', letterSpacing: '0.5px', uppercase: 'true', opacity: 0.7 }}>
          ВЫБЕРИТЕ ДАТУ
        </label>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(5, 1fr)', gap: '0.4rem' }}>
          {getNextDays().map((item) => {
            const isSelected = selectedDate === item.dateStr;
            return (
              <button
                key={item.dateStr}
                type="button"
                onClick={() => { setSelectedDate(item.dateStr); setError(''); }}
                style={{
                  padding: '0.7rem 0.2rem',
                  borderRadius: '10px',
                  border: isSelected ? '1px solid var(--primary)' : '1px solid rgba(128, 128, 128, 0.2)',
                  background: isSelected ? 'var(--primary)' : 'rgba(128, 128, 128, 0.04)',
                  color: isSelected ? '#ffffff' : 'var(--text)',
                  cursor: 'pointer',
                  fontWeight: isSelected ? '600' : '500',
                  fontSize: '0.85rem',
                  textAlign: 'center',
                  transition: 'all 0.2s ease',
                  fontFamily: 'inherit'
                }}
              >
                {item.label.split(',')[0]}
                <span style={{ display: 'block', fontSize: '0.95rem', fontWeight: '700', marginTop: '2px' }}>
                  {item.label.split(',')[1]}
                </span>
              </button>
            );
          })}
        </div>
      </div>

      {/* Выбор Времени */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.5rem' }}>
        <label style={{ fontSize: '0.85rem', fontWeight: '600', letterSpacing: '0.5px', opacity: 0.7 }}>
          ДОСТУПНОЕ ВРЕМЯ
        </label>
        <div style={{ display: 'grid', gridTemplateColumns: 'repeat(3, 1fr)', gap: '0.4rem' }}>
          {timeSlots.map((time) => {
            const isSelected = selectedTime === time;
            return (
              <button
                key={time}
                type="button"
                onClick={() => { setSelectedTime(time); setError(''); }}
                style={{
                  padding: '0.6rem',
                  borderRadius: '10px',
                  border: isSelected ? '1px solid var(--primary)' : '1px solid rgba(128, 128, 128, 0.2)',
                  background: isSelected ? 'var(--primary)' : 'rgba(128, 128, 128, 0.04)',
                  color: isSelected ? '#ffffff' : 'var(--text)',
                  cursor: 'pointer',
                  fontWeight: '600',
                  fontSize: '0.9rem',
                  transition: 'all 0.2s ease',
                  fontFamily: 'inherit'
                }}
              >
                {time}
              </button>
            );
          })}
        </div>
      </div>

      {/* Ввод телефона и сообщения */}
      <div style={{ display: 'flex', flexDirection: 'column', gap: '0.8rem', marginTop: '0.2rem' }}>
        <input
          type="tel"
          placeholder="Телефон (+79161234567)"
          value={phone}
          onChange={handlePhoneChange}
          required
          pattern="(\+7|8)\d{10}"
          title="Введите номер в формате +79161234567 или 89161234567"
          style={{ 
            padding: '0.8rem 1rem', 
            borderRadius: '12px', 
            border: error && !selectedDate ? '2px solid #D32F2F' : '1px solid rgba(128, 128, 128, 0.25)', 
            background: 'var(--bg)', 
            color: 'var(--text)', 
            fontFamily: 'inherit',
            outline: 'none',
            width: '100%',
            boxSizing: 'border-box',
            fontSize: '0.95rem'
          }}
        />
        
        <textarea 
          placeholder="Сообщение или пожелания (необязательно)" 
          value={message} 
          onChange={(e) => setMessage(e.target.value)}
          rows="2"
          style={{ 
            padding: '0.8rem 1rem', 
            borderRadius: '12px', 
            border: '1px solid rgba(128, 128, 128, 0.25)', 
            background: 'var(--bg)', 
            color: 'var(--text)', 
            fontFamily: 'inherit', 
            resize: 'none',
            outline: 'none',
            width: '100%',
            boxSizing: 'border-box',
            fontSize: '0.95rem'
          }} 
        />
      </div>
      
      {error && <p style={{ color: '#D32F2F', fontSize: '0.85rem', margin: 0, fontWeight: '600', textAlign: 'center' }}>{error}</p>}
      
      <button 
        type="submit" 
        style={{
          background: 'linear-gradient(135deg, var(--primary), var(--primary-light))',
          color: 'white',
          border: 'none',
          padding: '0.9rem',
          borderRadius: '12px',
          fontWeight: '600',
          fontSize: '1rem',
          cursor: 'pointer',
          fontFamily: 'inherit',
          transition: 'opacity 0.2s',
          width: '100%',
          boxShadow: '0 4px 12px rgba(0,0,0,0.1)'
        }}
      >
        Подтвердить запись
      </button>
    </form>
  );
};

export default TestDriveForm;
